// ===== GEMINI INSIDE GOOGLE SHEETS =====
// Menu Extensions > Apps Script. Delete what's there and paste this whole thing.
// Save with the disk icon. Go back to the sheet.
// In a cell type:   =GEMINI("summarize in 10 words", A2)
// (Depending on your locale the separator may be ";" instead of ",". If you get an error, try the other one)

const KEY   = "PASTE_YOUR_KEY_STARTING_WITH_AIza";
const MODEL = "gemini-2.5-flash";   // fast and cheap

/**
 * Asks Gemini about the content of a cell.
 * @param {string} instruction What you want it to do.
 * @param {string} text The cell it starts from.
 * @return {string} Gemini's response.
 * @customfunction
 */
function GEMINI(instruction, text) {
  if (!instruction) return "Missing instruction";

  const content = instruction + "\n\nTEXT:\n" + (text || "");
  const url = "https://generativelanguage.googleapis.com/v1beta/models/"
            + MODEL + ":generateContent";

  const options = {
    method: "post",
    contentType: "application/json",
    headers: { "x-goog-api-key": KEY },
    muteHttpExceptions: true,
    payload: JSON.stringify({
      contents: [{ parts: [{ text: content }] }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 800 }
    })
  };

  const response = UrlFetchApp.fetch(url, options);
  const code     = response.getResponseCode();
  const body     = JSON.parse(response.getContentText());

  if (code !== 200) {
    return "ERROR " + code + ": " +
      (body.error && body.error.message ? body.error.message : "no detail");
  }
  if (!body.candidates || !body.candidates.length) {
    return "No response (possibly blocked for safety)";
  }
  return body.candidates[0].content.parts[0].text.trim();
}
